let ihsanInstallPrompt=null; window.addEventListener("beforeinstallprompt",e=>{e.preventDefault();ihsanInstallPrompt=e;}); window.addEventListener("appinstalled",()=>{ihsanInstallPrompt=null;toast("تم تثبيت أكاديمية الإحسان على جهازك.");}); if ("serviceWorker" in navigator && location.protocol === "https:") { window.addEventListener("load", () => navigator.serviceWorker.register("/service-worker.js").catch(() => {})); }
window.addEventListener("error",function(e){var a=document.getElementById("app");if(a&&a.querySelector(".loading")){a.innerHTML="<section class=\"panel\"><h2>خطأ في تشغيل الواجهة</h2><p class=\"muted\"></p></section>";a.querySelector("p").textContent=(e.message||"JavaScript error")+" — "+(e.filename||"")+(e.lineno?":"+e.lineno:"");}});window.addEventListener("unhandledrejection",function(e){var a=document.getElementById("app");if(a&&a.querySelector(".loading"))a.textContent="تعذّر بدء الأكاديمية: "+String(e.reason&&e.reason.message||e.reason||"خطأ غير معروف");});
const $=s=>document.querySelector(s), app=$("#app");
const safeStore={get(k){try{return localStorage.getItem(k)||""}catch{return ""}},set(k,v){try{localStorage.setItem(k,v)}catch{}},remove(k){try{localStorage.removeItem(k)}catch{}}};
const S={token:safeStore.get("ihsan_token"),user:null,tab:"home",mode:"hub",groups:[],students:[],teachers:[],date:new Date().toISOString().slice(0,10)};
const themes=[{name:"زمردي",green:"#174b3b",mint:"#e8f3ec",gold:"#d4ad63",paper:"#fbfdf9"},{name:"أزرق",green:"#24558a",mint:"#e8f1fb",gold:"#d7b66c",paper:"#f9fcff"},{name:"بنفسجي",green:"#68456f",mint:"#f2eaf5",gold:"#d2b171",paper:"#fffbff"},{name:"رملي",green:"#77542f",mint:"#f5ecdf",gold:"#c2a05e",paper:"#fffdf8"}];
function applyTheme(){let i=Number(safeStore.get("ihsan_theme_index")||0);if(!Number.isInteger(i)||i<0||i>=themes.length)i=0;const t=themes[i];for(const [k,v] of Object.entries({green:t.green,mint:t.mint,gold:t.gold,paper:t.paper}))document.documentElement.style.setProperty("--"+k,v);document.documentElement.dataset.ihsanTheme=t.name;}
applyTheme();
const esc=v=>String(v==null?"":v).replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));
async function api(path,opt={}){const h={"content-type":"application/json",...(S.token?{authorization:"Bearer "+S.token}:{}),...(opt.headers||{})};const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),12000);try{const r=await fetch("/api"+path,{...opt,headers:h,signal:controller.signal});const raw=await r.text();let d;try{d=raw?JSON.parse(raw):{}}catch{const type=r.headers.get("content-type")||"غير محدد";const preview=raw.replace(/\\s+/g," ").slice(0,180);throw Error("رد غير صالح من الخادم — "+r.status+" — نوع المحتوى: "+type+(preview?" — "+preview:" — استجابة فارغة"))}if(!r.ok)throw Error(d.error||("فشل الطلب ("+r.status+")"));return d}catch(e){if(e.name==="AbortError")throw Error("انتهت مهلة الاتصال بالخادم بعد 12 ثانية أثناء انتظار الاستجابة. أعد المحاولة؛ إذا تكرر الأمر فالمشكلة في مسار API أو قاعدة البيانات.");if(e instanceof TypeError)throw Error("تعذّر الاتصال بخادم الأكاديمية. تحقق من الاتصال ثم أعد المحاولة.");throw e}finally{clearTimeout(timer)}}
function toast(t,err=false){const old=$(".toast");if(old)old.remove();const e=document.createElement("div");e.className="toast"+(err?" error":"");e.textContent=t;document.body.append(e);setTimeout(()=>e.remove(),3500)}
function renderTopActions(){ $("#top-actions").innerHTML='<button class="btn secondary" id="theme-toggle" type="button">تغيير اللون</button> <button class="btn secondary" id="install-app" type="button">تثبيت التطبيق</button>'+(S.user?' <button class="btn secondary" id="logout">خروج</button>':"");$("#theme-toggle")?.addEventListener("click",()=>{const i=(Number(safeStore.get("ihsan_theme_index")||0)+1)%themes.length;safeStore.set("ihsan_theme_index",String(i));applyTheme();toast("تم تغيير ألوان الأكاديمية إلى "+themes[i].name)});$("#logout")?.addEventListener("click",logout);$("#install-app")?.addEventListener("click",async()=>{if(ihsanInstallPrompt){ihsanInstallPrompt.prompt();try{await ihsanInstallPrompt.userChoice}catch{}ihsanInstallPrompt=null;return}const ua=navigator.userAgent||"";let msg="للتثبيت: افتح قائمة المتصفح ⋮ ثم اختر «تثبيت التطبيق» أو «إنشاء اختصار».";if(/iPhone|iPad|iPod/i.test(ua))msg="على iPhone/iPad: اضغط زر المشاركة في Safari ثم «إضافة إلى الشاشة الرئيسية».";else if(/Android/i.test(ua))msg="على Android: افتح القائمة ⋮ في Chrome ثم «تثبيت التطبيق» أو «إضافة إلى الشاشة الرئيسية».";else if(!/Chrome|Edg/i.test(ua))msg="افتح الرابط في Chrome أو Edge، ثم قائمة المتصفح واختر «تثبيت التطبيق» أو «تثبيت هذا الموقع كتطبيق».";alert(msg)})}
function auth(setup){renderTopActions();app.innerHTML='<div class="auth-layout"><section class="welcome"><div><span class="eyebrow">بِسْمِ اللهِ الرَّحْمَنِ الرَّحِيمِ</span><h1>علم نافع، وعمل صالح، وخُلُق حسن.</h1><p>مساحة هادئة لحفظ القرآن ومراجعته، ومتابعة التقدم خطوة بخطوة.</p></div><div class="verse">﴿ وَقُلْ رَبِّ زِدْنِي عِلْمًا ﴾</div></section><section class="panel stack">'+(setup?'<div class="notice">أول دخول: أنشئ حساب المدير مرة واحدة.</div>':'')+'<div><h2>'+(setup?"إعداد الأكاديمية":"تسجيل الدخول")+'</h2><p class="muted small">'+(setup?"احتفظ برمز الإعداد لنفسك فقط.":"استخدم اسم الدخول أو البريد الذي أنشأه لك المدير.")+'</p></div><form id="auth-form" class="stack">'+(setup?'<label class="field">رمز الإعداد<input name="code" type="password" required autocomplete="off"></label><label class="field">الاسم الكامل<input name="name" required maxlength="120"></label><label class="field">البريد الإلكتروني<input name="email" type="email" required></label><label class="field">كلمة مرور المدير (14 حرفًا على الأقل)<input name="password" type="password" minlength="14" required autocomplete="new-password"></label>':'<label class="field">اسم الدخول أو الاسم الكامل<input name="username" value="'+esc(safeStore.get("ihsan_last_identity"))+'" required autocomplete="username"></label><label class="field">كلمة المرور<input name="password" type="password" required autocomplete="current-password"></label><label class="remember-option"><input name="remember" type="checkbox" checked> تذكّر دخولي على هذا الجهاز لمدة تصل إلى 30 يومًا. لا تفعّلها على جهاز مشترك.</label>')+'<div id="auth-error" class="notice error hidden"></div><button class="btn" type="submit">'+(setup?"إنشاء حساب المدير":"دخول إلى الأكاديمية")+'</button></form></section></div>';
$("#auth-form").onsubmit=async e=>{e.preventDefault();const f=new FormData(e.currentTarget),b=e.currentTarget.querySelector("button"),err=$("#auth-error");b.disabled=true;err.classList.add("hidden");try{if(setup){await api("/admin/bootstrap",{method:"POST",headers:{"x-bootstrap-secret":String(f.get("code"))},body:JSON.stringify({name:f.get("name"),email:f.get("email"),password:f.get("password")})});toast("تم إنشاء المدير. سجّل الدخول.");auth(false)}else{const d=await api("/login",{method:"POST",body:JSON.stringify({identity:f.get("username"),password:f.get("password"),remember:f.get("remember")==="on"})});S.token=d.token;S.user=d.user;safeStore.set("ihsan_token",S.token);safeStore.set("ihsan_last_identity",String(f.get("username")||""));if("PasswordCredential" in window&&navigator.credentials&&navigator.credentials.store){try{await navigator.credentials.store(new PasswordCredential({id:String(f.get("username")),password:String(f.get("password")),name:d.user?.name||String(f.get("username"))}))}catch{}}await start()}}catch(x){err.textContent=x.message;err.classList.remove("hidden")}finally{b.disabled=false}}
}
async function boot(){try{const st=await api("/setup/status");if(!S.token){auth(st.needs_admin&&st.setup_enabled);return}try{S.user=await api("/me");await start()}catch{S.token="";safeStore.remove("ihsan_token");auth(st.needs_admin&&st.setup_enabled)}}catch{app.innerHTML='<div class="panel"><h2>تعذّر الاتصال</h2><p class="muted">تعذّر الوصول إلى قاعدة البيانات. حدّث الصفحة بعد قليل.</p><button class="btn" onclick="location.reload()">إعادة المحاولة</button></div>'}}
async function logout(){try{await api("/logout",{method:"POST",body:"{}"})}catch{}S.token="";S.user=null;safeStore.remove("ihsan_token");auth(false)}
async function load(){const r=await Promise.allSettled([api("/groups"),api("/students")]);S.groups=r[0].status==="fulfilled"?r[0].value:[];S.students=r[1].status==="fulfilled"?r[1].value:[];if(S.user.role==="admin")try{S.teachers=await api("/teachers")}catch{S.teachers=[]}}
function items(){if(S.mode==="ihsan")return [["all","نظرة عامة"],["allah","معرفة الله"],["prophet","الرسول ﷺ"],["quranpath","القرآن الكريم"],["sunnah","السنة والمتون"],["adab","الأدب والعمل"]];return S.user.role==="admin"?[["home","الرئيسية"],["groups","الأفواج"],["teachers","المعلمون"],["students","الطلاب"],["attendance","الحضور"],["reports","التقارير"],["leaderboard","ترتيب الفوج"],["quran","متابعة القرآن"],["tests","الاختبارات"],["posts","مكتبة الشيخ"],["notifications","التنبيهات"]]:S.user.role==="teacher"?[["home","الرئيسية"],["students","طلبتي"],["attendance","الحضور"],["reports","التقارير"],["leaderboard","ترتيب الفوج"],["quran","متابعة القرآن"],["tests","الاختبارات"],["posts","مكتبة الشيخ"],["notifications","التنبيهات"]]:[["home","الرئيسية"],["profile","ملفي"],["quran","تقدمي"],["attendance","حضوري"],["leaderboard","ترتيب الفوج"],["tests","اختباراتي"],["posts","مكتبة الشيخ"],["notifications","التنبيهات"]]}
async function start(){renderTopActions();S.tab="home";S.mode="hub";moduleChooser(false)}
function moduleChooser(push=true){if(push){try{history.pushState({ihsanMode:"hub"},"",location.pathname)}catch{}}renderTopActions();app.innerHTML='<section class="module-welcome"><span class="eyebrow">أَكَادِيمِيَّةُ الإِحْسَانِ فِي بِنَاءِ الإِنْسَان</span><h1>اختر وجهتك اليوم</h1><p>مساحتان متكاملتان، لكل واحدة طريقها وأدواتها، بحساب واحد.</p></section><div class="module-grid"><button class="module-card school-module" id="open-school"><span class="module-symbol">⌂</span><span class="module-label">المدرسة القرآنية</span><span class="module-desc">الحفظ والمراجعة، الأفواج، الطلاب، المعلمون، الحضور والمتابعة.</span><span class="module-link">الدخول إلى المدرسة ←</span></button><button class="module-card ihsan-module" id="open-ihsan"><span class="module-symbol">✦</span><span class="module-label">منهج الإحسان</span><span class="module-desc">رحلة تعلّم لبناء المعرفة والإيمان والأدب والعمل الصالح خطوةً خطوة.</span><span class="module-link">الدخول إلى المنهج ←</span></button></div><p class="module-foot">«وَقُلْ رَبِّ زِدْنِي عِلْمًا»</p>';
$("#open-school").onclick=async()=>{try{history.pushState({ihsanMode:"school",ihsanTab:"home"},"",location.pathname)}catch{}S.mode="school";S.tab="home";await load();shell();await page()};
$("#open-ihsan").onclick=()=>{try{history.pushState({ihsanMode:"ihsan",ihsanTab:"all"},"",location.pathname)}catch{}S.mode="ihsan";S.tab="all";shell();page()}}

function shell(){app.innerHTML='<div class="hero"><span class="eyebrow">أَكَادِيمِيَّةُ الإِحْسَان</span><h1>مرحبًا، '+esc(S.user.name)+'</h1><p>'+(S.user.role==="admin"?"صلاحيات المدير والمعلم مفعّلة؛ يمكنك إدارة الأكاديمية ومتابعة أفواج الحضور والحفظ.":S.user.role==="teacher"?"متابعة الطلبة والحضور والتقدم في الحفظ.":"اجعل لك اليوم وردًا صغيرًا ثابتًا، واحتفِ بجهدك.")+'</p><button class="btn secondary module-switch" id="switch-module">تبديل الواجهة</button></div><div class="layout"><nav class="sidebar">'+items().map(x=>'<button class="nav-btn '+(S.tab===x[0]?"active":"")+'" data-tab="'+x[0]+'">'+x[1]+'</button>').join("")+'</nav><section id="view" class="content"><div class="loading">جار التحميل…</div></section></div>';document.querySelectorAll(".nav-btn").forEach(b=>b.onclick=()=>go(b.dataset.tab));$("#switch-module")?.addEventListener("click",moduleChooser)}
function curriculumPage(v){
const lessons={
all:["رحلة الإحسان","منهج متدرّج يجمع العلم النافع والعمل الصالح وحسن الخلق.","ابدأ بمعرفة الله، ثم تعرّف إلى رسوله ﷺ، وعش مع القرآن حفظًا وفهمًا وعملًا، وتعلّم السنة والآداب التي تظهر أثر العلم في حياتك."],
allah:["معرفة الله تعالى","تعلّم أسماء الله الحسنى ومعانيها وآثارها في القلب والعمل.","المحور: الاسم ومعناه، ما يدل عليه من كمال الله تعالى، ثمرة الإيمان به، ودعاء أو عمل تعبّدي يناسبه. ابدأ باسم واحد، وافهمه، واستحضره في يومك."],
prophet:["معرفة الرسول ﷺ","سيرة نبوية، شمائل، مواقف، ومحبة تظهر في الاتباع.","تعلّم نسبه وبعثته ورحمته وهديه، ثم اختر خُلُقًا نبويًا واحدًا تطبّقه اليوم. محبة النبي ﷺ تُثمر اتباع سنته وحسن الاقتداء به."],
quranpath:["القرآن الكريم","حفظٌ ومراجعةٌ وفهمٌ وتدبّرٌ وعمل.","اجعل لك وردًا ثابتًا يناسب قدرتك. اقرأ الآيات بتأنٍّ، افهم معناها من تفسير موثوق، استخرج هداية واحدة، ثم اسأل نفسك: كيف أعمل بها؟"],
sunnah:["السنة والمتون","أحاديث مختارة ومتون تأسيسية في العلم الشرعي.","ابدأ بالأحاديث الجامعة والمتون المناسبة لمستواك. احفظ النص مضبوطًا، وافهم ألفاظه، وتحقّق من شرحه ومصدره، ثم حوّل العلم إلى سلوك."],
adab:["الأدب والعمل","تزكية النفس، آداب طالب العلم، ومهارات الحياة النافعة.","من علامات العلم النافع التواضع والصدق والرفق واحترام الوقت. اختر خُلُقًا واحدًا لهذا الأسبوع، وراقب تطبيقه، وراجع نفسك برفق."]
};
const x=lessons[S.tab]||lessons.all;
v.innerHTML='<div class="curriculum-banner"><span class="eyebrow">مَنْهَجُ الإِحْسَان</span><h2>'+x[0]+'</h2><p>'+x[1]+'</p></div><div class="card curriculum-card"><h3>خطوتك التعليمية</h3><p>'+x[2]+'</p><div class="notice">قاعدة المنهج: تعلّم قليلًا بإتقان، وطبّق ما تعلّمت، ثم راجع واستمر.</div></div><div class="curriculum-tiles"><button class="curriculum-tile" data-lesson="allah"><strong>الله تعالى</strong><span>الأسماء الحسنى والإيمان</span></button><button class="curriculum-tile" data-lesson="prophet"><strong>الرسول ﷺ</strong><span>السيرة والشمائل والاتباع</span></button><button class="curriculum-tile" data-lesson="quranpath"><strong>القرآن</strong><span>حفظ وفهم وتدبر وعمل</span></button><button class="curriculum-tile" data-lesson="sunnah"><strong>السنة والمتون</strong><span>حديث وعلم شرعي</span></button><button class="curriculum-tile" data-lesson="adab"><strong>الأدب والعمل</strong><span>أخلاق وتطبيق ومراجعة</span></button></div>';
v.querySelectorAll("[data-lesson]").forEach(b=>b.onclick=()=>{S.tab=b.dataset.lesson;shell();page()})
}

const head=(a,b)=>'<div class="section-head"><div><h2>'+a+'</h2><p>'+b+'</p></div></div>';
const field=(label,name,type="text",min="")=>'<label class="field">'+label+'<input name="'+name+'" type="'+type+'" '+(min?'minlength="'+min+'"':"")+' required></label>';
const groupOpts=()=>S.groups.map(g=>'<option value="'+esc(g.id)+'">'+esc(g.name)+'</option>').join("");
function go(id){try{history.pushState({ihsanMode:S.mode,ihsanTab:id},"",location.pathname+"#"+encodeURIComponent(id))}catch{}S.tab=id;shell();page()}
window.addEventListener("popstate",async e=>{if(!S.user)return;const st=e.state||{};if(st.ihsanMode==="hub"){S.mode="hub";moduleChooser(false);return;}if(st.ihsanMode==="school"||st.ihsanMode==="ihsan"){S.mode=st.ihsanMode;S.tab=st.ihsanTab||(S.mode==="ihsan"?"all":"home");if(S.mode==="school")await load();shell();await page();if(st.ihsanSubView==="student-profile")await studentProfile($("#view"),st.studentId);return;}S.mode="hub";moduleChooser(false);});
async function page(){const v=$("#view");if(S.mode==="ihsan")return curriculumPage(v);v.innerHTML='<div class="loading">جار تحميل البيانات…</div>';try{if(S.tab==="home")return await home(v);if(S.tab==="groups")return groups(v);if(S.tab==="teachers")return teachers(v);if(S.tab==="students")return students(v);if(S.tab==="attendance")return attendance(v);if(S.tab==="reports")return reportsPage(v);if(S.tab==="leaderboard")return leaderboardPage(v);if(S.tab==="profile")return studentProfile(v,S.user.student_id);if(S.tab==="quran")return quran(v);if(S.tab==="tests")return testsPage(v);if(S.tab==="posts")return postsPage(v);if(S.tab==="notifications")return notificationsPage(v)}catch(e){v.innerHTML='<div class="panel"><h2>تعذّر تحميل البيانات</h2><p class="notice error">'+esc(e.message)+'</p><button class="btn" id="retry">إعادة المحاولة</button></div>';$("#retry").onclick=page}}
async function home(v){const d=await api("/dashboard");let html=head("الرئيسية","نظرة مختصرة على يومك.");if(S.user.role!=="student")html+='<div class="stats"><div class="stat"><small>الطلاب</small><strong>'+d.students_count+'</strong></div><div class="stat"><small>الأفواج</small><strong>'+d.groups_count+'</strong></div><div class="stat"><small>سُجّل حضورهم اليوم</small><strong>'+d.attendance_marked+'</strong></div></div>';else html+='<div class="card"><div class="student-welcome">﴿ وَقُلْ رَبِّ زِدْنِي عِلْمًا ﴾</div><p class="muted">خطوة ثابتة كل يوم خير من انقطاع طويل. راجع وردك ثم دوّن ما أنجزت.</p></div>';html+='<div class="card"><h3>خطوات سريعة</h3><div class="list">'+items().filter(x=>x[0]!=="home").map(x=>'<button class="list-row nav-btn" data-go="'+x[0]+'"><strong>'+x[1]+'</strong><span>←</span></button>').join("")+'</div></div>';v.innerHTML=html;v.querySelectorAll("[data-go]").forEach(b=>b.onclick=()=>go(b.dataset.go))}
function groups(v){
const teacherOptions=(selected)=>'<option value="">غير معيّن</option>'+(S.user.role==="admin"?'<option value="'+esc(S.user.id)+'" '+(S.user.id===selected?'selected':'')+'>'+esc(S.user.name)+' — مدير ومعلم</option>':"")+S.teachers.map(t=>'<option value="'+esc(t.id)+'" '+(t.id===selected?'selected':'')+'>'+esc(t.name)+' ('+esc(t.username)+')</option>').join("");
v.innerHTML=head("الأفواج","أنشئ الأفواج وعيّن المعلم أو غيّر تعيينه في أي وقت.")+'<div class="card"><form id="gform" class="form-grid"><div class="wide">'+field("اسم الفوج","name")+'</div><label class="field wide">المعلم المسؤول<select name="teacher_id">'+teacherOptions("")+'</select></label><div class="wide"><button class="btn">إضافة الفوج</button></div></form></div><div class="divider"></div><div class="list">'+(S.groups.length?S.groups.map(g=>'<div class="list-row"><div style="flex:1;min-width:220px"><strong>'+esc(g.name)+'</strong><label class="field small">المعلم المسؤول<select data-teacher-for="'+esc(g.id)+'">'+teacherOptions(g.teacher_id)+'</select></label></div><button class="btn" data-save-group="'+esc(g.id)+'">حفظ التعيين</button><button class="btn danger" data-del="'+esc(g.id)+'">إيقاف</button></div>').join(""):'<div class="empty">لا توجد أفواج بعد.</div>')+'</div>';
$("#gform").onsubmit=async e=>{e.preventDefault();const f=new FormData(e.currentTarget);try{await api("/groups",{method:"POST",body:JSON.stringify({name:f.get("name"),teacher_id:f.get("teacher_id")})});toast("تمت إضافة الفوج");await load();shell();page()}catch(x){toast(x.message,true)}};
v.querySelectorAll("[data-save-group]").forEach(b=>b.onclick=async()=>{const id=b.dataset.saveGroup,sel=v.querySelector('[data-teacher-for="'+id+'"]');try{await api("/groups/"+encodeURIComponent(id),{method:"PATCH",body:JSON.stringify({teacher_id:sel.value||null})});toast("تم حفظ تعيين المعلم");await load();shell();page()}catch(x){toast(x.message,true)}});
v.querySelectorAll("[data-del]").forEach(b=>b.onclick=async()=>{if(!confirm("إيقاف الفوج؟"))return;try{await api("/groups/"+b.dataset.del,{method:"DELETE"});await load();shell();page()}catch(x){toast(x.message,true)}})
}
function teachers(v){v.innerHTML=head("المعلمون","أنشئ حساب دخول لكل معلم.")+'<div class="card"><form id="tform" class="form-grid"><div>'+field("الاسم الكامل","name")+'</div><div>'+field("كلمة مرور مؤقتة (8 أحرف على الأقل)","password","password","8")+'</div><div class="wide"><button class="btn">إنشاء حساب المعلم</button></div></form><p class="muted small">سلّم كلمة المرور للمعلم بطريقة خاصة.</p></div><div class="divider"></div><div class="list">'+(S.teachers.length?S.teachers.map(t=>'<div class="list-row"><div><strong>'+esc(t.name)+'</strong><small>اسم الدخول: '+esc(t.username)+'</small></div><button class="btn" data-edit-teacher="'+esc(t.id)+'">تعديل</button></div>').join(""):'<div class="empty">لا يوجد معلمون بعد.</div>')+'</div>';$("#tform").onsubmit=async e=>{e.preventDefault();const f=new FormData(e.currentTarget);try{await api("/teachers",{method:"POST",body:JSON.stringify({name:f.get("name"),username:String(f.get("name")||"").trim(),password:f.get("password")})});toast("تم إنشاء حساب المعلم؛ اسم الدخول ظاهر في القائمة");await load();shell();page()}catch(x){toast(x.message,true)}};
v.querySelectorAll("[data-edit-teacher]").forEach(b=>b.onclick=async()=>{const t=S.teachers.find(x=>x.id===b.dataset.editTeacher);if(!t)return;const name=prompt("الاسم الكامل:",t.name);if(name===null)return;const username=prompt("اسم الدخول:",t.username);if(username===null)return;const password=prompt("كلمة مرور جديدة (اتركها فارغة للإبقاء على الحالية):","");if(password===null)return;try{await api("/teachers/"+t.id,{method:"PATCH",body:JSON.stringify({name,username,password})});toast("تم تعديل حساب المعلم");await load();shell();page()}catch(x){toast(x.message,true)}})}
function students(v){
const groupName=id=>(S.groups.find(g=>g.id===id)||{}).name||"بلا فوج";
v.innerHTML=head("الطلاب","اختر الفوج لعرض طلابه منفصلين. الحسابات الموجودة تبقى كما هي.")+(S.groups.length?'<div class="card"><form id="sform" class="form-grid"><div>'+field("اسم الطالب الكامل","name")+'</div><div>'+field("كلمة مرور مؤقتة","password","password","8")+'</div><label class="field">الفوج<select name="group_id" required><option value="">اختر الفوج</option>'+groupOpts()+'</select></label><div class="wide"><button class="btn">إنشاء حساب طالب</button></div></form><p class="muted small">هذا النموذج ينشئ حساب دخول. الطلاب المسجلون في القائمة الاسمية دون حساب يظهرون منفصلين ولا يتطلبون كلمة مرور.</p></div>':'<div class="notice">أنشئ فوجًا أولًا، ثم أضف الطلاب إليه.</div>')+'<div class="card"><label class="field">فرز القائمة حسب الفوج<select id="student-group-filter"><option value="all">كل الأفواج — عرض منفصل</option>'+S.groups.slice().sort((a,b)=>a.name.localeCompare(b.name,"ar")).map(g=>'<option value="'+esc(g.id)+'">'+esc(g.name)+'</option>').join("")+'</select></label></div><div id="students-roster"></div>';
const host=$("#students-roster");
function renderRoster(){
const selected=$("#student-group-filter")?.value||"all";
const groups=S.groups.slice().sort((a,b)=>a.name.localeCompare(b.name,"ar")).filter(g=>selected==="all"||g.id===selected);
let html="";
for(const g of groups){
const list=S.students.filter(s=>s.group_id===g.id).slice().sort((a,b)=>String(a.name||"").localeCompare(String(b.name||""),"ar"));
html+='<section class="card"><h3>'+esc(g.name)+' <span class="muted small">('+list.length+')</span></h3><div class="list">'+(list.length?list.map(s=>{const availableGroups=S.groups.filter(x=>x.id!==s.group_id);const actions=S.user.role==="student"?"":'<button class="btn secondary" data-profile-student="'+esc(s.id)+'">ملف الطالب</button>'+(!s.user_id?'<button class="btn" data-create-student-account="'+esc(s.id)+'">إنشاء دخول</button>':'<button class="btn" data-edit-student="'+esc(s.id)+'">تعديل الحساب</button>')+(availableGroups.length?'<span class="move-control"><select data-move-student="'+esc(s.id)+'" aria-label="الفوج الجديد">'+availableGroups.map(g2=>'<option value="'+esc(g2.id)+'">'+esc(g2.name)+'</option>').join("")+'</select><button class="btn secondary" data-save-move="'+esc(s.id)+'">نقل الفوج</button></span>':"")+(s.user_id?'<button class="btn danger" data-del-student="'+esc(s.id)+'">تعطيل</button>':"");return '<div class="list-row student-row"><div><strong>'+esc(s.name)+'</strong><small>'+(s.user_id?'اسم الدخول: '+esc(s.username||"غير متاح"):'قائمة اسمية — بلا حساب دخول')+'</small></div><div class="student-actions">'+actions+'</div></div>'}).join(""):'<div class="empty">لا يوجد طلاب في هذا الفوج.</div>')+'</div></section>';
}
if(selected==="all"){
const ungrouped=S.students.filter(s=>!S.groups.some(g=>g.id===s.group_id)).slice().sort((a,b)=>String(a.name||"").localeCompare(String(b.name||""),"ar"));
if(ungrouped.length)html+='<section class="card"><h3>طلاب بلا فوج ('+ungrouped.length+')</h3><div class="list">'+ungrouped.map(s=>'<div class="list-row"><div><strong>'+esc(s.name)+'</strong><small>'+(s.user_id?'اسم الدخول: '+esc(s.username||"غير متاح"):'قائمة اسمية — بلا حساب دخول')+'</small></div></div>').join("")+'</div></section>';
}
host.innerHTML=html||'<div class="empty">لا توجد أفواج لعرضها.</div>';
host.querySelectorAll("[data-profile-student]").forEach(b=>b.onclick=()=>{const id=b.dataset.profileStudent;try{history.pushState({ihsanMode:"school",ihsanTab:"students",ihsanSubView:"student-profile",studentId:id},"",location.pathname+"#student-"+encodeURIComponent(id))}catch{}studentProfile(v,id)});
host.querySelectorAll("[data-create-student-account]").forEach(b=>b.onclick=async()=>{const student=S.students.find(x=>x.id===b.dataset.createStudentAccount);if(!student)return;const username=prompt("اسم الدخول للطالب:",student.name);if(username===null||!username.trim())return;const password=prompt("كلمة مرور مؤقتة (8 أحرف على الأقل):","");if(password===null)return;if(password.length<8)return toast("كلمة المرور يجب أن تكون 8 أحرف على الأقل",true);try{const result=await api("/students/"+encodeURIComponent(student.id)+"/account",{method:"POST",body:JSON.stringify({username:username.trim(),password})});toast("أُنشئ حساب الطالب. اسم الدخول: "+result.username);await load();shell();page()}catch(x){toast(x.message,true)}});
host.querySelectorAll("[data-save-move]").forEach(b=>b.onclick=async()=>{const id=b.dataset.saveMove,select=host.querySelector('[data-move-student="'+id+'"]');if(!select||!select.value)return toast("اختر الفوج الجديد",true);const student=S.students.find(x=>x.id===id);if(!student||student.group_id===select.value)return toast("اختر فوجًا مختلفًا",true);if(!confirm("نقل "+student.name+" إلى الفوج المحدد؟ سيبقى سجل الحفظ والحضور السابق محفوظًا."))return;try{await api("/students/"+encodeURIComponent(id),{method:"PATCH",body:JSON.stringify({group_id:select.value})});toast("تم نقل الطالب مع الاحتفاظ بسجله");await load();shell();page()}catch(x){toast(x.message,true)}});
host.querySelectorAll("[data-edit-student]").forEach(b=>b.onclick=async()=>{const s=S.students.find(x=>x.id===b.dataset.editStudent);if(!s)return;const name=prompt("اسم الطالب الكامل:",s.name);if(name===null)return;const username=prompt("اسم الدخول:",s.username||s.name);if(username===null)return;const password=prompt("كلمة مرور جديدة (اتركها فارغة للإبقاء على الحالية):","");if(password===null)return;try{await api("/students/"+s.id,{method:"PATCH",body:JSON.stringify({name,username,password})});toast("تم تعديل حساب الطالب");await load();shell();page()}catch(x){toast(x.message,true)}});
host.querySelectorAll("[data-del-student]").forEach(b=>b.onclick=async()=>{if(!confirm("تعطيل حساب الطالب؟"))return;try{await api("/students/"+b.dataset.delStudent,{method:"DELETE"});await load();shell();page()}catch(x){toast(x.message,true)}});
}
$("#student-group-filter").onchange=renderRoster;
renderRoster();
$("#sform")?.addEventListener("submit",async e=>{e.preventDefault();const f=new FormData(e.currentTarget);try{const created=await api("/students",{method:"POST",body:JSON.stringify({name:f.get("name"),username:String(f.get("name")||"").trim(),password:f.get("password"),group_id:f.get("group_id")})});toast("تم إنشاء الطالب؛ اسم الدخول: "+created.username);await load();shell();page()}catch(x){toast(x.message,true)}});
}
async function attendance(v){
if(S.user.role==="student"){const rows=await api("/attendance?date="+S.date);v.innerHTML=head("حضوري","سجل الحضور الخاص بك.")+'<div class="card"><label class="field">التاريخ<input id="date" type="date" value="'+S.date+'"></label><div class="divider"></div><div class="list">'+(rows.length?rows.map(r=>'<div class="list-row"><div><strong>'+esc(r.date)+'</strong><small>'+esc(r.note||"")+'</small></div><span class="pill">'+({"present":"حاضر","absent":"غائب","late":"متأخر","excused":"بعذر"}[r.status]||r.status)+'</span></div>').join(""):'<div class="empty">لا يوجد سجل لهذا التاريخ.</div>')+'</div></div>';$("#date").onchange=()=>{S.date=$("#date").value;attendance(v)};return}
v.innerHTML=head("الحضور","اختر الفوج والتاريخ، ثم عاين السجل أو افتح نموذج التعديل قبل الحفظ.")+'<div class="card"><div class="attendance-controls"><label class="field">الفوج<select id="ag"><option value="">اختر الفوج</option>'+groupOpts()+'</select></label><label class="field">التاريخ<input id="ad" type="date" value="'+S.date+'"></label><button id="preview-att" class="btn secondary">معاينة الحضور</button><button id="load-att" class="btn">تسجيل / تعديل الحضور</button></div><div id="att-list" class="muted small">اختر الفوج والتاريخ ثم اضغط «معاينة الحضور» لعرض السجل دون تعديل.</div></div>';
$("#ad").onchange=()=>S.date=$("#ad").value;
async function showAttendance(edit){
const group=$("#ag").value,date=$("#ad").value;if(!group)return toast("اختر الفوج",true);
try{
const pair=await Promise.all([api("/students?group_id="+encodeURIComponent(group)),api("/attendance?group_id="+encodeURIComponent(group)+"&date="+encodeURIComponent(date))]);
const students=pair[0],old={};pair[1].forEach(x=>old[x.student_id]=x);const host=$("#att-list");
if(!students.length){host.innerHTML='<div class="empty">لا يوجد طلاب في هذا الفوج.</div>';return}
const statusName=x=>({"present":"حاضر","absent":"غائب","late":"متأخر","excused":"بعذر"}[x]||"غير مسجل");
if(!edit){host.innerHTML='<div class="card"><h3>معاينة سجل الحضور</h3><p class="muted small">'+esc((S.groups.find(g=>g.id===group)||{}).name||"الفوج")+' · '+esc(date)+' · '+students.length+' طالبًا</p><div class="table-wrap"><table><thead><tr><th>الطالب</th><th>الحالة المسجلة</th><th>الملاحظة</th></tr></thead><tbody>'+students.map(st=>'<tr><td>'+esc(st.name)+'</td><td><span class="pill">'+statusName(old[st.id]?.status)+'</span></td><td>'+esc(old[st.id]?.note||"—")+'</td></tr>').join("")+'</tbody></table></div><p class="muted small">هذه معاينة فقط؛ لم يُحفظ أي تغيير.</p><button id="edit-after-preview" class="btn">تعديل هذا السجل</button></div>';$("#edit-after-preview").onclick=()=>showAttendance(true);return}
host.innerHTML='<form id="attform"><p class="muted small">غيّر الحالات ثم اضغط «حفظ الحضور». لن تُحفظ التغييرات قبل الضغط.</p><div class="table-wrap"><table><thead><tr><th>الطالب</th><th>الحالة</th><th>ملاحظة</th></tr></thead><tbody>'+students.map(st=>'<tr><td>'+esc(st.name)+'</td><td><select class="status-select" name="st_'+esc(st.id)+'"><option value="present" '+((old[st.id]?.status||"present")==="present"?"selected":"")+'>حاضر</option><option value="absent" '+(old[st.id]?.status==="absent"?"selected":"")+'>غائب</option><option value="late" '+(old[st.id]?.status==="late"?"selected":"")+'>متأخر</option><option value="excused" '+(old[st.id]?.status==="excused"?"selected":"")+'>بعذر</option></select></td><td><input name="note_'+esc(st.id)+'" value="'+esc(old[st.id]?.note||"")+'" style="width:120px" placeholder="اختياري"></td></tr>').join("")+'</tbody></table></div><button class="btn" style="margin-top:15px">حفظ الحضور</button><button type="button" id="back-preview" class="btn secondary" style="margin:15px 8px 0">رجوع إلى المعاينة</button></form>';
$("#back-preview").onclick=()=>showAttendance(false);
$("#attform").onsubmit=async e=>{e.preventDefault();const f=new FormData(e.currentTarget);const items=students.map(st=>({student_id:st.id,status:f.get("st_"+st.id),note:f.get("note_"+st.id)}));try{const r=await api("/attendance",{method:"POST",body:JSON.stringify({group_id:group,date,items})});toast("تم حفظ حضور "+r.saved+" طالبًا");showAttendance(false)}catch(x){toast(x.message,true)}}
}catch(x){toast(x.message,true)}
}
$("#preview-att").onclick=()=>showAttendance(false);$("#load-att").onclick=()=>showAttendance(true)
}
async function quran(v){if(S.user.role==="student"){const rows=await api("/quran/progress");v.innerHTML=head("تقدمي في القرآن","ما سجّله المعلم من حفظ ومراجعة.")+'<div class="card"><div class="list">'+(rows.length?rows.map(r=>'<div class="list-row"><div><strong>'+esc(r.date)+'</strong><small>الحفظ: '+esc(r.memorized||"—")+' · المراجعة: '+esc(r.reviewed||"—")+' · '+esc(r.notes||"")+'</small></div><span class="pill">متابعة</span></div>').join(""):'<div class="empty">لم تُسجّل متابعة بعد. سيظهر تقدمك هنا عندما يضيف المعلم سجلًا.</div>')+'</div></div>';return}
v.innerHTML=head("متابعة القرآن","دوّن الحفظ والمراجعة لكل طالب.")+'<div class="card"><form id="qform" class="form-grid"><label class="field wide">الطالب<select name="student_id" required><option value="">اختر الطالب</option>'+S.students.map(s=>'<option value="'+esc(s.id)+'">'+esc(s.name)+' — '+esc((S.groups.find(g=>g.id===s.group_id)||{}).name||"")+'</option>').join("")+'</select></label><div>'+field("الحفظ الجديد","memorized")+'</div><div>'+field("المراجعة","reviewed")+'</div><label class="field wide">ملاحظات<textarea name="notes" maxlength="500"></textarea></label><div>'+field("التاريخ","date","date")+'</div><div class="wide"><button class="btn">حفظ المتابعة</button></div></form></div><div class="divider"></div><div id="qhistory" class="list"><div class="empty">اختر طالبًا لعرض سجله.</div></div>';$("#qform").elements.date.value=S.date;$("#qform").elements.student_id.onchange=async()=>{const id=$("#qform").elements.student_id.value;if(!id)return;try{const rows=await api("/quran/progress?student_id="+encodeURIComponent(id));$("#qhistory").innerHTML=rows.length?rows.map(r=>'<div class="list-row"><div><strong>'+esc(r.date)+'</strong><small>الحفظ: '+esc(r.memorized||"—")+' · المراجعة: '+esc(r.reviewed||"—")+' · '+esc(r.notes||"")+'</small></div></div>').join(""):'<div class="empty">لا توجد متابعة لهذا الطالب.</div>'}catch(x){toast(x.message,true)}};$("#qform").onsubmit=async e=>{e.preventDefault();const f=new FormData(e.currentTarget);try{await api("/quran/progress",{method:"POST",body:JSON.stringify({student_id:f.get("student_id"),memorized:f.get("memorized"),reviewed:f.get("reviewed"),notes:f.get("notes"),date:f.get("date")})});toast("تم حفظ متابعة القرآن");e.currentTarget.reset();e.currentTarget.elements.date.value=S.date;$("#qhistory").innerHTML='<div class="notice">حُفظت المتابعة بنجاح.</div>'}catch(x){toast(x.message,true)}}}


async function studentProfile(v,id){
 const st=S.students.find(x=>x.id===id);
 if(!st){v.innerHTML=head("ملف الطالب","لم يعد الطالب ظاهرًا في هذا الفوج.");return}
 v.innerHTML=head("ملف الطالب",st.name+" · "+((S.groups.find(g=>g.id===st.group_id)||{}).name||"بلا فوج"))+'<button id="back-students" class="btn secondary">العودة إلى قائمة الطلاب</button><div class="loading">جار تحميل السجل…</div>';
 $("#back-students").onclick=()=>{S.tab="students";shell();page()};
 const isStudent=S.user.role==="student",base=st.group_id?"/attendance?group_id="+encodeURIComponent(st.group_id)+"&history=1&student_id="+encodeURIComponent(st.id):"/attendance?history=1";
 try{
  const jobs=[api("/quran/progress"+(isStudent?"":"?student_id="+encodeURIComponent(st.id))),api(base)];
  jobs.push(api("/test-history?student_id="+encodeURIComponent(st.id)));
  const data=await Promise.all(jobs),progress=data[0]||[],attendanceRows=data[1]||[],testRows=data[2]||[];
  const present=attendanceRows.filter(x=>x.status==="present").length,absent=attendanceRows.filter(x=>x.status==="absent").length,late=attendanceRows.filter(x=>x.status==="late").length;
  let html=head("ملخص الطالب",st.name)+'<div class="stats"><div class="stat"><small>سجلات الحضور</small><strong>'+attendanceRows.length+'</strong></div><div class="stat"><small>الحضور</small><strong>'+present+'</strong></div><div class="stat"><small>الغياب</small><strong>'+absent+'</strong></div><div class="stat"><small>التأخر</small><strong>'+late+'</strong></div><div class="stat"><small>متابعات القرآن</small><strong>'+progress.length+'</strong></div><div class="stat"><small>محاولات الاختبارات</small><strong>'+testRows.length+'</strong></div></div><section class="card"><h3>سجل الحضور</h3><div class="list">'+(attendanceRows.length?attendanceRows.slice(0,40).map(r=>'<div class="list-row"><div><strong>'+esc(r.date)+'</strong><small>'+esc(r.note||"")+'</small></div><span class="pill">'+({"present":"حاضر","absent":"غائب","late":"متأخر","excused":"بعذر"}[r.status]||"غير مسجل")+'</span></div>').join(""):'<div class="empty">لا توجد سجلات حضور لهذا الطالب.</div>')+'</div></section><section class="card"><h3>متابعة القرآن</h3><div class="list">'+(progress.length?progress.map(r=>'<div class="list-row"><div><strong>'+esc(r.date)+'</strong><small>الحفظ: '+esc(r.memorized||"—")+' · المراجعة: '+esc(r.reviewed||"—")+' · '+esc(r.notes||"")+'</small></div></div>').join(""):'<div class="empty">لا توجد متابعة قرآنية مسجّلة.</div>')+'</div></section>';
  html+='<section class="card"><h3>نتائج الاختبارات</h3><div class="list">'+(testRows.length?testRows.map(r=>'<div class="list-row"><div><strong>'+esc(r.title||"اختبار")+'</strong><small>'+esc(r.submitted_at||"")+'</small></div><strong>'+r.score+' / '+r.total+'</strong></div>').join(""):'<div class="empty">لا توجد نتائج اختبارات لهذا الطالب.</div>')+'</div></section>';
  v.innerHTML=html+'<button id="back-students-bottom" class="btn secondary">العودة إلى قائمة الطلاب</button>';$("#back-students-bottom").onclick=()=>{S.tab="students";shell();page()};
 }catch(e){v.innerHTML=head("ملف الطالب",st.name)+'<div class="notice error">'+esc(e.message)+'</div><button class="btn secondary" id="back-students">العودة إلى قائمة الطلاب</button>';$("#back-students").onclick=()=>{S.tab="students";shell();page()}}
}
async function reportsPage(v){
 if(S.user.role==="student"){v.innerHTML=head("التقارير","غير مسموح");return}
 v.innerHTML=head("التقارير الأسبوعية","ملخص الحضور لكل طالب في الفوج المحدد، دون حذف السجلات القديمة.")+'<section class="card"><label class="field">الفوج<select id="report-group">'+groupOpts()+'</select></label><button class="btn" id="load-report" style="margin-top:12px">عرض تقرير آخر 7 أيام</button></section><div id="report-result" class="loading">اختر الفوج ثم اعرض التقرير.</div>';
 const render=async()=>{const gid=$("#report-group").value;if(!gid)return toast("اختر الفوج",true);const host=$("#report-result");host.innerHTML='<div class="loading">جار إعداد التقرير…</div>';try{const rows=await api("/attendance?group_id="+encodeURIComponent(gid)+"&history=1");const since=new Date();since.setUTCDate(since.getUTCDate()-6);const cutoff=since.toISOString().slice(0,10);const week=rows.filter(r=>String(r.date)>=cutoff);const students=S.students.filter(st=>st.group_id===gid).slice().sort((a,b)=>String(a.name).localeCompare(String(b.name),"ar"));const count=(id,status)=>week.filter(r=>r.student_id===id&&r.status===status).length;const present=week.filter(r=>r.status==="present").length,absent=week.filter(r=>r.status==="absent").length,late=week.filter(r=>r.status==="late").length,marked=week.length;host.innerHTML='<div class="stats"><div class="stat"><small>سجلات الأسبوع</small><strong>'+marked+'</strong></div><div class="stat"><small>حاضر</small><strong>'+present+'</strong></div><div class="stat"><small>غائب</small><strong>'+absent+'</strong></div><div class="stat"><small>متأخر</small><strong>'+late+'</strong></div></div><section class="card"><h3>تفصيل الطلاب · '+esc(cutoff)+' إلى '+esc(new Date().toISOString().slice(0,10))+'</h3><div class="table-wrap"><table><thead><tr><th>الطالب</th><th>حاضر</th><th>غائب</th><th>متأخر</th><th>بعذر</th><th>السجلات</th></tr></thead><tbody>'+students.map(st=>'<tr><td>'+esc(st.name)+'</td><td>'+count(st.id,"present")+'</td><td>'+count(st.id,"absent")+'</td><td>'+count(st.id,"late")+'</td><td>'+count(st.id,"excused")+'</td><td>'+week.filter(r=>r.student_id===st.id).length+'</td></tr>').join("")+'</tbody></table></div></section>'}catch(e){host.innerHTML='<div class="notice error">'+esc(e.message)+'</div>'}};
 $("#load-report").onclick=render;if(S.groups.length)render();
}

async function leaderboardPage(v){
 const isStudent=S.user.role==="student";
 const staff=S.user.role==="admin"||S.user.role==="teacher";
 let groupId=isStudent?(S.user.group_id||((S.groups[0]||{}).id||"")):"";
 if(staff&&S.groups.length)groupId=S.groups[0].id;
 v.innerHTML=head("ترتيب الفوج","ترتيب تشجيعي يقدّر المواظبة والحفظ ونتائج الاختبارات، لا يقيس قيمة الطالب ولا يستبدل تقييم المعلم.")+
 (staff?'<section class="card"><label class="field">الفوج<select id="leaderboard-group">'+groupOpts()+'</select></label><button class="btn" id="leaderboard-refresh" style="margin-top:12px">تحديث الترتيب</button></section>':'<p class="muted small">يعرض هذا الترتيب طلاب فوجك فقط. النقاط: 5 للحضور المسجّل، و10 لكل متابعة قرآن، و3 لكل إجابة صحيحة في أفضل محاولة لكل اختبار.</p>')+
 '<div id="leaderboard-content" class="loading">جار حساب النقاط…</div>';
 const render=async()=>{
  const group=staff?($("#leaderboard-group")?.value||""):groupId;
  const host=$("#leaderboard-content");
  if(staff&&!group){host.innerHTML='<div class="empty">اختر فوجًا لعرض ترتيبه.</div>';return}
  host.innerHTML='<div class="loading">جار حساب النقاط…</div>';
  try{
   const rows=await api("/leaderboard"+(staff?"?group_id="+encodeURIComponent(group):""));
   if(!rows.length){host.innerHTML='<div class="card empty">لا توجد بيانات كافية للترتيب بعد. يبدأ الترتيب مع تسجيل الحضور ومتابعة القرآن والاختبارات.</div>';return}
   host.innerHTML='<section class="card"><div class="table-wrap"><table><thead><tr><th>الترتيب</th><th>الطالب</th><th>النقاط</th><th>الحضور</th><th>متابعة القرآن</th><th>إجابات صحيحة</th></tr></thead><tbody>'+rows.map(r=>'<tr '+(r.is_self?'class="leaderboard-self"':"")+'><td>'+r.rank+'</td><td>'+esc(r.name)+(r.is_self?' <span class="pill">أنت</span>':"")+'</td><td><strong>'+r.points+'</strong></td><td>'+r.present_days+'</td><td>'+r.quran_records+'</td><td>'+r.quiz_correct+'</td></tr>').join("")+'</tbody></table></div><p class="muted small">النقاط أداة تحفيز قابلة للتحسين، وقد لا تعبّر وحدها عن جودة الحفظ أو الإتقان.</p></section>';
  }catch(e){host.innerHTML='<div class="notice error">'+esc(e.message)+'</div>'}
 };
 $("#leaderboard-refresh")?.addEventListener("click",render);
 $("#leaderboard-group")?.addEventListener("change",render);
 if(!staff||S.groups.length)await render();
}

function questionEditor(n){return '<div class="question-builder" data-question><h4>السؤال '+n+'</h4><label class="field">نص السؤال<textarea data-q-prompt required maxlength="500" placeholder="اكتب السؤال هنا"></textarea></label><div class="form-grid">'+[0,1,2,3].map(i=>'<label class="field">الخيار '+(i+1)+'<input data-q-choice="'+i+'" required maxlength="250" placeholder="نص الخيار"></label>').join("")+'</div><label class="field">الإجابة الصحيحة<select data-q-correct><option value="0">الخيار الأول</option><option value="1">الخيار الثاني</option><option value="2">الخيار الثالث</option><option value="3">الخيار الرابع</option></select></label></div>'}
async function testsPage(v){
 const isStudent=S.user.role==="student";
 let tests=[];
 try{tests=await api("/tests")}catch(e){v.innerHTML=head("الاختبارات","تعذّر جلب الاختبارات.")+'<div class="notice error">'+esc(e.message)+'</div>';return}
 let html=head(isStudent?"اختباراتي":"إدارة الاختبارات","اختبارات اختيار من متعدد تُصحّح آليًا وتُحفظ نتائجها في ملف الطالب.");
 if(!isStudent){
  html+='<section class="card"><h3>إنشاء اختبار</h3><form id="test-create-form" class="stack"><label class="field">عنوان الاختبار<input name="title" required maxlength="160"></label><label class="field">وصف مختصر<textarea name="description" maxlength="2000"></textarea></label><label class="field">الفوج المستهدف<select name="group_id" '+(S.user.role==="admin"?"":"required")+'>'+(S.user.role==="admin"?'<option value="">اختبار عام لجميع الطلاب</option>':'<option value="">اختر فوجًا</option>')+groupOpts()+'</select></label><label class="field">آخر موعد (اختياري)<input name="due_date" type="date"></label><div id="questions-editor">'+questionEditor(1)+'</div><button type="button" class="btn secondary" id="add-question">إضافة سؤال آخر</button><button class="btn" type="submit">نشر الاختبار</button><p class="muted small">اختر الإجابة الصحيحة لكل سؤال. يمكن إضافة حتى 30 سؤالًا في الاختبار.</p></form></section><div class="divider"></div>';
  html+='<h3>الاختبارات المنشورة</h3><div class="list">'+(tests.length?tests.map(t=>'<section class="card"><div class="list-row"><div><strong>'+esc(t.title)+'</strong><small>'+(t.group_id?esc((S.groups.find(g=>g.id===t.group_id)||{}).name||"فوج"):"اختبار عام")+' · '+(t.questions||[]).length+' سؤال'+(t.due_date?' · الموعد: '+esc(t.due_date):"")+'</small></div><div class="student-actions"><button class="btn secondary" data-test-results="'+esc(t.id)+'">النتائج</button><button class="btn danger" data-test-delete="'+esc(t.id)+'">حذف</button></div></div><div data-results-host="'+esc(t.id)+'"></div></section>').join(""):'<div class="empty">لم تُنشأ اختبارات بعد.</div>')+'</div>';
 }else{
  html+='<div class="list">'+(tests.length?tests.map(t=>'<section class="card"><h3>'+esc(t.title)+'</h3><p class="muted small">'+esc(t.description||"")+(t.due_date?' · آخر موعد: '+esc(t.due_date):"")+'</p>'+(t.my_attempt?'<div class="notice">آخر نتيجة: '+t.my_attempt.score+' / '+t.my_attempt.total+' · '+Math.round(100*t.my_attempt.score/Math.max(1,t.my_attempt.total))+'% · '+esc(t.my_attempt.submitted_at||"")+'</div>':"")+'<form class="quiz-form" data-submit-test="'+esc(t.id)+'">'+(t.questions||[]).map((q,qi)=>'<fieldset class="question-view"><legend>'+(qi+1)+'. '+esc(q.prompt)+'</legend>'+(q.choices||[]).map((choice,ci)=>'<label class="quiz-option"><input type="radio" name="q_'+esc(q.id)+'" value="'+ci+'" required> '+esc(choice)+'</label>').join("")+'</fieldset>').join("")+'<button class="btn" type="submit">إرسال الإجابات وتصحيحها</button></form></section>').join(""):'<div class="empty">لا توجد اختبارات منشورة لفوجك حاليًا.</div>')+'</div>';
 }
 v.innerHTML=html;
 if(!isStudent){
  $("#add-question")?.addEventListener("click",()=>{const host=$("#questions-editor");if(host.querySelectorAll("[data-question]").length>=30)return toast("الحد الأقصى 30 سؤالًا",true);host.insertAdjacentHTML("beforeend",questionEditor(host.querySelectorAll("[data-question]").length+1))});
  $("#test-create-form")?.addEventListener("submit",async e=>{e.preventDefault();const form=e.currentTarget,f=new FormData(form);const questions=[...form.querySelectorAll("[data-question]")].map(q=>({prompt:q.querySelector("[data-q-prompt]").value.trim(),choices:[...q.querySelectorAll("[data-q-choice]")].map(x=>x.value.trim()),correct_index:Number(q.querySelector("[data-q-correct]").value)}));if(questions.some(q=>!q.prompt||q.choices.some(c=>!c))){toast("أكمل نص كل سؤال وخياراته الأربعة",true);return}try{const result=await api("/tests",{method:"POST",body:JSON.stringify({title:f.get("title"),description:f.get("description"),group_id:f.get("group_id"),due_date:f.get("due_date"),questions})});toast("نُشر الاختبار وحُفظت إجاباته الصحيحة");await load();shell();await page()}catch(x){toast(x.message,true)}});
  v.querySelectorAll("[data-test-delete]").forEach(b=>b.onclick=async()=>{if(!confirm("حذف هذا الاختبار؟ ستبقى محاولات الطلاب السابقة محفوظة في السجل."))return;try{await api("/test-delete",{method:"POST",body:JSON.stringify({id:b.dataset.testDelete})});toast("تم حذف الاختبار من قائمة النشر");await page()}catch(x){toast(x.message,true)}});
  v.querySelectorAll("[data-test-results]").forEach(b=>b.onclick=async()=>{const host=v.querySelector('[data-results-host="'+b.dataset.testResults+'"]');try{const rows=await api("/test-results?id="+encodeURIComponent(b.dataset.testResults));host.innerHTML='<div class="result-list">'+(rows.length?rows.map(r=>'<div class="list-row"><span>'+esc((S.students.find(st=>st.id===r.student_id)||{}).name||"طالب")+'</span><strong>'+r.score+' / '+r.total+'</strong><small>'+esc(r.submitted_at||"")+'</small></div>').join(""):'<p class="muted">لم يقدّم أي طالب هذا الاختبار بعد.</p>')+'</div>'}catch(x){toast(x.message,true)}});
 }else{
  v.querySelectorAll("[data-submit-test]").forEach(form=>form.onsubmit=async e=>{e.preventDefault();const test=tests.find(t=>t.id===form.dataset.submitTest);if(!test)return;const answers=(test.questions||[]).map(q=>{const chosen=form.querySelector('input[name="q_'+q.id+'"]:checked');return {question_id:q.id,selected_index:chosen?Number(chosen.value):-1}});if(answers.some(a=>a.selected_index<0)){toast("أجب عن جميع الأسئلة أولًا",true);return}try{const result=await api("/test-submit?id="+encodeURIComponent(test.id),{method:"POST",body:JSON.stringify({answers})});toast("نتيجتك: "+result.score+" من "+result.total+" ("+result.percent+"%)");await page()}catch(x){toast(x.message,true)}});
 }
}
